#pragma once
#include "native_hc_fixture.hpp"
#include "native_qsa_norm_rope_layout.hpp"
namespace native_qsa_nr {
using namespace native_hc_fixture;
// The host oracle also validates indexer-internal pooled positions; this does
// not widen the separate model norm/RoPE execution admission.
struct Fixture{uint32_t cols=256,rows=4,stride=256,theta=strata::core::portable_detail::native_qsa_theta_scale();std::vector<float>x,gamma;std::vector<int32_t>pos;};
inline void validate(const Fixture&f){strata::core::portable_detail::native_qsa_norm_rope_geometry(f.cols,f.rows,f.stride,f.theta);native_hc_need(f.x.size()==f.rows*f.stride&&f.gamma.size()==f.cols&&f.pos.size()==f.rows,"QSA norm/RoPE fixture spans");for(size_t r=0;r<f.rows;++r){native_hc_need(f.pos[r]>=0&&f.pos[r]<=4095,"QSA position domain");for(size_t c=0;c<f.cols;++c)native_hc_normal(f.x[r*f.stride+c]);}for(float v:f.gamma)native_hc_normal(v);}
inline Fixture synthetic(unsigned mode,unsigned width=256,bool strided=false){native_hc_need(mode<4,"QSA fixture mode");Fixture f;f.cols=width;f.stride=strided?2*width:width;f.x.assign(f.rows*f.stride,value(0x4acaf00d));f.gamma.resize(width);f.pos={0,1,127,255};for(size_t c=0;c<width;++c)f.gamma[c]=mode?float(int(c%9)-4)/4.f:1.f;
 for(size_t r=0;r<f.rows;++r)for(size_t c=0;c<width;++c){float x=0;if(mode==1&&(c==0||c==32||c==63||c==width-1))x=float(int(c%7)-3)/2.f;if(mode==2)x=float(int((r*17+c*23)%41)-20)/16.f;if(mode==3)x=(c%4<2?1.f:-1.f)*std::ldexp(float(c%7+1),int(r)*8-12);f.x[r*f.stride+c]=x;}validate(f);return f;}
inline void write(const std::string&p,const Fixture&f){validate(f);native_hc_need(!std::filesystem::exists(p),"QSA fresh fixture");std::ofstream o(p,std::ios::binary);for(uint32_t v:{0x3152514eu,1u,f.cols,f.rows,f.stride,f.theta})word(o,v);for(auto*v:{&f.x,&f.gamma})for(float x:*v)word(o,bits(x));for(int32_t v:f.pos)word(o,uint32_t(v));native_hc_need(bool(o),"QSA fixture write");}
inline Fixture read(const std::string&p){std::ifstream i(p,std::ios::binary);native_hc_need(bool(i)&&word(i)==0x3152514e&&word(i)==1,"QSA fixture header");Fixture f;f.cols=word(i);f.rows=word(i);f.stride=word(i);f.theta=word(i);strata::core::portable_detail::native_qsa_norm_rope_geometry(f.cols,f.rows,f.stride,f.theta);f.x.resize(f.rows*f.stride);f.gamma.resize(f.cols);f.pos.resize(f.rows);for(auto*v:{&f.x,&f.gamma})for(float&x:*v)x=value(word(i));for(auto&x:f.pos)x=int32_t(word(i));native_hc_need(i.peek()==EOF,"QSA fixture trailing bytes");validate(f);return f;}
inline void contract(const Fixture&f,const std::string&p){native_hc_need(!std::filesystem::exists(p),"QSA fresh output contract");std::ofstream o(p);o<<"{\"fields\":{\"normalized.f32le\":"<<f.rows*f.cols*4<<",\"rotated.f32le\":"<<f.rows*f.cols*4<<",\"diag.f32le\":"<<f.rows*130*4<<"},\"qualified\":false}\n";native_hc_need(bool(o),"QSA output contract");}
// Independent source-order control. Intrinsic values are the actual backend's
// emitted rs/pow/cos/sin; their numerical qualification is separate.
struct Control{std::vector<float>arg,normalized,rotated;};
inline Control control(const Fixture&f,const std::vector<float>&diag){validate(f);native_hc_need(diag.size()==f.rows*130,"QSA diagnostic shape");Control z{std::vector<float>(f.rows),std::vector<float>(f.rows*f.cols),std::vector<float>(f.rows*f.cols)};
 for(size_t r=0;r<f.rows;++r){std::array<float,256>a{};for(size_t c=0;c<f.cols;++c)a[c]=native_hc_normal(f.x[r*f.stride+c]*f.x[r*f.stride+c]);for(size_t o:{16,8,4,2,1}){auto prev=a;for(size_t c=0;c<256;++c)a[c]=native_hc_normal(prev[c]+prev[c^o]);}std::array<float,32>b{};for(size_t c=0;c<8;++c)b[c]=a[c*32];for(size_t o:{16,8,4,2,1}){auto prev=b;for(size_t c=0;c<32;++c)b[c]=native_hc_normal(prev[c]+prev[c^o]);}float mean=native_hc_normal(b[0]/float(f.cols));z.arg[r]=native_hc_normal(mean+1e-6f);float rs=diag[r*130+1];for(size_t c=0;c<f.cols;++c)z.rotated[r*f.cols+c]=z.normalized[r*f.cols+c]=native_hc_normal(native_hc_normal(rs*f.x[r*f.stride+c])*f.gamma[c]);for(size_t c=0;c<32;++c){float x=z.normalized[r*f.cols+c],y=z.normalized[r*f.cols+c+32],co=diag[r*130+66+c],si=diag[r*130+98+c];float bs=native_hc_normal(y*si),bc=native_hc_normal(y*co);z.rotated[r*f.cols+c]=native_hc_normal(std::fma(x,co,-bs));z.rotated[r*f.cols+c+32]=native_hc_normal(std::fma(x,si,bc));}}
 return z;}
inline std::vector<float> get(const std::filesystem::path&p,size_t n){std::ifstream i(p,std::ios::binary);native_hc_need(bool(i),"QSA result missing");std::vector<float>v(n);for(float&x:v)x=value(word(i));native_hc_need(i.peek()==EOF,"QSA result span");return v;}
inline void exact(const std::vector<float>&a,const std::vector<float>&b,const char*msg){native_hc_need(a.size()==b.size()&&!std::memcmp(a.data(),b.data(),a.size()*4),msg);}
}
